insert into public.recipe_ingredients (recipe_id,position,name,quantity,unit,note) values ('10000000-0000-4000-8000-000000000034'::uuid,7,'Cumin moulu',1.0000,'c. à thé',null);
insert into public.recipe_ingredients (recipe_id,position,name,quantity,unit,note) values ('10000000-0000-4000-8000-000000000034'::uuid,8,'Poivre noir',0.5000,'c. à thé',null);
insert into public.recipe_ingredients (recipe_id,position,name,quantity,unit,note) values ('10000000-0000-4000-8000-000000000034'::uuid,9,'Œufs durs',2.0000,'unité','hachés');
insert into public.recipe_ingredients (recipe_id,position,name,quantity,unit,note) values ('10000000-0000-4000-8000-000000000034'::uuid,10,'Olives vertes',80.0000,'g','hachées');
insert into public.recipe_ingredients (recipe_id,position,name,quantity,unit,note) values ('10000000-0000-4000-8000-000000000034'::uuid,11,'Huile neutre',1.0000,'c. à soupe','pour la garniture');
insert into public.recipe_ingredients (recipe_id,position,name,quantity,unit,note) values ('10000000-0000-4000-8000-000000000034'::uuid,12,'Œuf battu',1.0000,'unité','pour dorer');
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000027'::uuid,0,'Faire dorer les lardons dans une cocotte puis les réserver. Saisir ensuite les cubes de bœuf en plusieurs fois jusqu’à belle coloration.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000027'::uuid,1,'Ajouter carottes et ail. Saupoudrer de farine, mélanger puis verser le vin rouge et le bouillon. Ajouter bouquet garni, lardons, sel et poivre.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000027'::uuid,2,'Porter à frémissement, couvrir partiellement et cuire très doucement environ 2 h 30, jusqu’à ce que le bœuf soit presque tendre.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000027'::uuid,3,'Faire revenir séparément les champignons et les petits oignons jusqu’à légère coloration. Les ajouter à la cocotte et poursuivre 30 à 40 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000027'::uuid,4,'Cuire les pommes de terre à l’eau salée, les égoutter puis les écraser avec beurre et lait chaud pour obtenir une purée lisse.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000027'::uuid,5,'Servir le bœuf bourguignon sur la purée, en répartissant viande, carottes, champignons et petits oignons. Parsemer de persil frais.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000028'::uuid,0,'Faire fondre environ la moitié du beurre avec la moelle, si utilisée, puis cuire doucement l’oignon jusqu’à transparence sans le colorer.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000028'::uuid,1,'Ajouter le riz et le nacrer 2 minutes. Verser le vin blanc et laisser évaporer.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000028'::uuid,2,'Ajouter le bouillon bouillant une louche à la fois en remuant régulièrement et en attendant que le liquide soit presque absorbé avant la suivante.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000028'::uuid,3,'Infuser le safran dans une petite louche de bouillon chaud puis l’ajouter environ aux deux tiers de la cuisson.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000028'::uuid,4,'Lorsque le riz est al dente, retirer du feu. Incorporer le reste de beurre froid et le Parmesan pour obtenir une texture crémeuse et souple, dite all’onda.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000028'::uuid,5,'Goûter et ajuster le sel seulement si nécessaire. Servir immédiatement, sans garniture supplémentaire afin de correspondre à la photo de référence.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000029'::uuid,0,'Trancher l’agneau le plus finement possible. Saler et poivrer légèrement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000029'::uuid,1,'Cuire les tomates et le concentré ensemble 15 à 20 minutes jusqu’à obtenir une sauce lisse et assez épaisse. Saler au goût.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000029'::uuid,2,'Faire griller ou poêler les fines tranches d’agneau à feu très vif en petites quantités afin qu’elles brunissent rapidement sans sécher.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000029'::uuid,3,'Réchauffer le pide puis le couper en bouchées. Répartir le pain sur quatre assiettes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000029'::uuid,4,'Déposer l’agneau chaud sur le pide puis napper de sauce tomate.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000029'::uuid,5,'Ajouter le yaourt nature sur le dessus ou sur le côté, comme dans la présentation photographiée, et servir immédiatement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000030'::uuid,0,'Faire dorer ou griller légèrement les tranches de pommes de terre et d’aubergine avec une partie de l’huile. Réserver.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000030'::uuid,1,'Faire revenir les oignons dans un peu d’huile, ajouter le bœuf haché et cuire en l’émiettant. Ajouter vin blanc, concentré de tomate, cannelle, sel et poivre puis laisser réduire.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000030'::uuid,2,'Dans un plat à gratin, former une couche de pommes de terre, puis une couche d’aubergines, la viande, puis le reste des aubergines.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000030'::uuid,3,'Préparer la béchamel : faire fondre le beurre, ajouter la farine, puis incorporer progressivement le lait chaud. Saler, poivrer, muscader, épaissir puis retirer du feu et incorporer l’œuf.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000030'::uuid,4,'Étendre la béchamel sur la moussaka et cuire au four à 180 °C environ 40 minutes, jusqu’à ce que le dessus soit bien doré. Laisser reposer 15 minutes avant de couper.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000030'::uuid,5,'Pour la salade, couper tomates, concombre, oignon et poivron. Ajouter olives, feta, un filet de l’huile d’olive restante et l’origan.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000030'::uuid,6,'Servir une part de moussaka avec la salade grecque et du pain, conformément à la photo de référence.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000031'::uuid,0,'Mixer Scotch bonnet, pimento, thym, oignons verts, oignon, ail, sel, poivre et huile jusqu’à obtenir une pâte grossière.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000031'::uuid,1,'Faire plusieurs entailles peu profondes dans le poulet. Masser avec la pâte jerk et laisser mariner au réfrigérateur au moins 4 heures, idéalement toute une nuit.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000031'::uuid,2,'Préparer un barbecue pour cuisson indirecte moyenne. Ajouter du bois de pimento si disponible pour obtenir la fumée traditionnelle.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000031'::uuid,3,'Déposer le poulet sur la zone indirecte et cuire couvercle fermé en le retournant régulièrement jusqu’à cuisson complète, environ 40 à 50 minutes selon les morceaux.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000031'::uuid,4,'Terminer quelques minutes au-dessus de la chaleur directe pour obtenir des bords bien grillés et légèrement noircis.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000031'::uuid,5,'Servir le poulet jerk tel quel, sans accompagnement ajouté, afin de correspondre à la photo de référence prise en Jamaïque.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000032'::uuid,0,'Piler ou mixer ail, persil, une partie de l’oignon et un peu de piment. Inciser les darnes de poisson et y insérer un peu de cette farce aromatique.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000032'::uuid,1,'Dans une grande marmite, chauffer l’huile et faire revenir le reste d’oignon. Ajouter tomates et concentré de tomate puis cuire jusqu’à ce que la base soit concentrée.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000032'::uuid,2,'Ajouter l’eau, le poisson séché, le laurier et les légumes les plus longs à cuire : manioc, carottes, chou et patate douce. Laisser frémir.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000032'::uuid,3,'Ajouter ensuite aubergine et gombo, puis les darnes de poisson et les mollusques. Cuire délicatement jusqu’à ce que poisson et légumes soient cuits sans se défaire.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000032'::uuid,4,'Retirer poisson et légumes. Prélever le bouillon nécessaire pour cuire les brisures de riz directement dans la sauce tomate jusqu’à absorption et tendreté.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000032'::uuid,5,'Dresser le riz dans un grand plat puis disposer le poisson et les légumes au-dessus, en veillant à montrer chou, carotte, aubergine, manioc/patate douce et autres légumes comme sur la photo.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000033'::uuid,0,'Mettre l’agneau dans une grande casserole avec oignon, cardamome, laurier et suffisamment d’eau pour couvrir. Laisser frémir jusqu’à ce que la viande soit très tendre, environ 90 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000033'::uuid,1,'Réhydrater le jameed conformément au produit puis le mixer avec un peu de liquide de cuisson jusqu’à texture lisse. Ajouter le yaourt si nécessaire pour obtenir une sauce acidulée mais onctueuse.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000033'::uuid,2,'Filtrer le bouillon d’agneau. En utiliser une partie pour cuire le riz jusqu’à tendreté.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000033'::uuid,3,'Ajouter la sauce au jameed à l’agneau et laisser frémir doucement 15 à 20 minutes sans faire bouillir trop fort.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000033'::uuid,4,'Tapisser un grand plateau de pain shrak. Humidifier le pain avec un peu de sauce, puis couvrir de riz.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000033'::uuid,5,'Déposer les morceaux d’agneau sur le riz, napper d’un peu de sauce au jameed puis garnir d’amandes, pignons et persil. Servir le reste de sauce à côté.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000034'::uuid,0,'Mélanger farine et une partie du sel. Sabler avec le saindoux ou le beurre puis ajouter l’eau progressivement pour former une pâte souple. Pétrir brièvement, couvrir et laisser reposer 30 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000034'::uuid,1,'Faire revenir les oignons dans l’huile jusqu’à transparence. Ajouter le bœuf et cuire juste jusqu’à ce qu’il perde sa couleur crue.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000034'::uuid,2,'Assaisonner avec paprika, cumin, poivre et le reste de sel. Retirer du feu et laisser refroidir complètement, puis incorporer œufs durs et olives.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000034'::uuid,3,'Abaisser la pâte et découper 12 disques d’environ 13 à 14 cm. Déposer une portion de farce au centre de chacun.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000034'::uuid,4,'Humidifier légèrement le bord, plier en demi-lune, bien sceller puis réaliser le repulgue en pinçant et repliant le bord.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000034'::uuid,5,'Déposer sur une plaque, badigeonner d’œuf battu et cuire à 210 °C environ 18 à 22 minutes, jusqu’à ce que les empanadas soient bien dorées.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000034'::uuid,6,'Servir seules, sans accompagnement extérieur, afin de correspondre à la photo de référence.',null,null);
