values ('10000000-0000-4000-8000-000000000027'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Bœuf bourguignon','boeuf-bourguignon','Bœuf braisé longuement au vin rouge de Bourgogne avec lard, carottes, champignons et petits oignons, servi sur une purée de pommes de terre et fini au persil.','Bœuf mijoté au vin rouge avec lard, champignons, petits oignons et purée.','fr','FR','Bourgogne-Franche-Comté','Mijoté','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'hard'::public.recipe_difficulty,35,210,6.00,now(),(select id from public.culinary_places where slug='fr-bourgogne-franche-comte'),true,'France.fr','https://www.france.fr/fr/article/recette-boeuf-bourguignon/','Version éditoriale adaptée à partir de la recette France.fr et à la présentation de la photo : bœuf, vin rouge, lard, carottes, champignons, petits oignons, purée et persil.')
