values ('10000000-0000-4000-8000-000000000028'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Risotto alla Milanese','risotto-alla-milanese','Risotto milanais crémeux au safran, préparé avec riz, bouillon de viande, oignon, beurre et Parmesan.','Le risotto doré au safran emblématique de Milan.','fr','IT','Milan','Risotto','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'medium'::public.recipe_difficulty,15,25,6.00,now(),(select id from public.culinary_places where slug='it-milan'),true,'YesMilano','https://www.yesmilano.it/en/articles/risotto-alla-milanese','La recette suit les éléments documentés par YesMilano : riz, beurre, moelle de veau facultative, oignon, vin blanc, bouillon, safran et Parmesan.')
