values ('10000000-0000-4000-8000-000000000030'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Moussaka grecque avec salade et pain','moussaka-grecque-salade','Moussaka grecque en couches de pommes de terre, aubergines, bœuf haché et béchamel, servie avec salade grecque et pain.','Moussaka au bœuf et aubergine avec béchamel, salade grecque et pain.','fr','GR','Grèce','Gratin','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'hard'::public.recipe_difficulty,55,70,8.00,now(),(select id from public.culinary_places where slug='gr'),true,'Visit Greece','https://www.visitgreece.gr/el/experiences/gastronomy/recipes/mousaka/','La moussaka suit la recette de Visit Greece. Une salade grecque et du pain sont ajoutés uniquement parce qu’ils sont clairement visibles sur la photo de référence prise dans une taverne de Laconie.')
