values ('10000000-0000-4000-8000-000000000031'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Poulet jerk jamaïcain','poulet-jerk-jamaicain','Poulet mariné aux piments Scotch bonnet, pimento, thym, oignons, échalotes et ail puis fumé/grillé lentement.','Poulet jamaïcain fumé et épicé au pimento et Scotch bonnet.','fr','JM','Jamaïque','Poulet grillé','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'medium'::public.recipe_difficulty,25,55,6.00,now(),(select id from public.culinary_places where slug='jm'),true,'Visit Jamaica','https://www.visitjamaica.com/blog/post/the-secret-to-true-jamaican-jerk/','Visit Jamaica identifie six ingrédients intrinsèques au jerk : pimento/allspice, thym, scallion, oignon, ail et Scotch bonnet. La source précise aussi que le vrai jerk est fumé sur bois de pimento.')
