values ('10000000-0000-4000-8000-000000000032'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Ceebu jën de Saint-Louis','ceebu-jen-saint-louis','Plat sénégalais de poisson et brisures de riz cuits avec tomate, poisson séché et un assortiment de légumes.','Le plat de poisson et riz originaire des communautés de pêcheurs de Saint-Louis.','fr','SN','Saint-Louis','Poisson et riz','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'hard'::public.recipe_difficulty,45,100,8.00,now(),(select id from public.culinary_places where slug='sn-saint-louis'),true,'UNESCO','https://ich.unesco.org/fr/RL/le-ceebu-jen-art-culinaire-du-senegal-01748','L’UNESCO documente l’origine à Saint-Louis et énumère les composants typiques : darne de poisson, brisures de riz, poisson séché, mollusques et légumes comme oignon, persil, ail, piment, tomate, carotte, aubergine, chou, manioc, patate douce, gombo et laurier.')
