values ('10000000-0000-4000-8000-000000000033'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Mansaf jordanien','mansaf-jordanien','Agneau tendre servi sur pain shrak et riz, nappé de sauce au jameed puis garni d’amandes, pignons et persil.','Le plat jordanien d’agneau, riz et jameed servi sur pain fin.','fr','JO','Jordanie','Agneau et riz','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'hard'::public.recipe_difficulty,35,120,8.00,now(),(select id from public.culinary_places where slug='jo'),true,'Visit Jordan','https://international.visitjordan.com/unesco/','Visit Jordan décrit le mansaf comme agneau tendre, riz, sauce acidulée au jameed et pain shrak. Les amandes, pignons et persil sont ajoutés parce qu’ils sont visibles sur la photo retenue.')
