values ('10000000-0000-4000-8000-000000000034'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Empanadas argentines au bœuf','empanadas-argentines-boeuf','Empanadas au four garnies de bœuf assaisonné, oignon, œuf dur et olives, refermées avec le repulgue traditionnel.','Empanadas argentines au bœuf cuites au four.','fr','AR','Argentine','Pâté salé','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'medium'::public.recipe_difficulty,50,25,12.00,now(),(select id from public.culinary_places where slug='ar'),true,'Visit Argentina','https://www.argentina.travel/novedades/la-ruta-de-la-empanada-donde-degustar-este-clasico-argentino-en-buenos-aires','Visit Argentina décrit l’empanada comme une icône nationale avec de nombreuses variantes régionales. Cette version éditoriale utilise une garniture au bœuf très classique et une cuisson au four; la photo ne montre aucun accompagnement extérieur.')
